SELECT tb.id, tb.user_id, tb.table_id AS time_table_id, tb.title,
       tb.status, tb.width, tb.start_at, tb.color, tb.schedule_id
FROM time_blocks tb
JOIN schedule s ON s.id = tb.schedule_id
WHERE tb.schedule_id = #{scheduleId}
  AND tb.user_id = #{userId}
  AND s.user_id = #{userId}


JOIN time_tables t ON t.id = tb.table_id
WHERE tb.table_id = #{timeTableId}
  AND tb.user_id = #{userId}
  AND t.user_id = #{userId}
  AND tb.status = 'PLACED'

