UPDATE time_blocks 
SET table_id = #{timeBlock.timeTableId},
    title = #{timeBlock.title},
    status = #{timeBlock.status},
    schedule_id = #{timeBlock.relatedSchedule.id},
    width = #{timeBlock.width},
    start_at = #{timeBlock.startAt},
    color = #{timeBlock.color}
WHERE id = #{timeBlock.id} AND user_id = #{userId}


    AND EXISTS(
        SELECT 1
        FROM time_tables tt
        WHERE tt.id = #{timeBlock.timeTableId} AND tt.user_id = #{userId}
    )


     AND EXISTS(
        SELECT 1
        FROM schedule s
        WHERE s.id = #{timeBlock.relatedSchedule.id}
          AND s.user_id = #{userId}
     )

UPDATE time_blocks 
SET start_at = #{startAt}
WHERE id = #{id} AND user_id = #{userId}
